/** Builds docs/cli.md from the command definitions. `bun run docs` writes it; the tests check it is current. */
import { resolve } from "node:path";
import { commands } from "../src/commands/index.ts";
import { commandHelp } from "../src/framework.ts";

export function cliReference(): string {
  const sections = commands.map((c) => `## devit ${c.path.join(" ")}\n\n\`\`\`\n${commandHelp(c).trimEnd()}\n\`\`\``);
  return [
    "# CLI reference",
    "",
    "<!-- Generated by `bun run docs` from src/commands. Do not edit by hand. -->",
    "",
    "Every command accepts `--json`, `-p <slug>` and `--help`.",
    "",
    sections.join("\n\n"),
    "",
  ].join("\n");
}

if (import.meta.main) {
  await Bun.write(resolve(import.meta.dir, "../docs/cli.md"), cliReference());
  console.log("wrote docs/cli.md");
}
